package server

// router_coverage_test.go adds targeted coverage tests to push the server
// package above the 80% floor that applies to any touched package.
//
// These tests construct NewRouter with non-nil handlers to exercise the
// nil-guarded registration branches that the minimal NewRouter(nil...) calls
// in router_metrics_test.go and security_headers_test.go cannot reach.
//
// Every handler used here is a stub whose methods do nothing — the router
// tests only inspect route registration, never invoke business logic.

import (
	"context"
	"net/http"
	"net/http/httptest"
	"net/netip"
	"testing"

	"github.com/stretchr/testify/require"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/idempotency"
	"github.com/zenithflowinc/omnicore-platform/services/admin-bff/internal/handlers"
)

// stubIdempotencyStore is a no-op idempotency.Store for tests that build a
// router with idempotency-wrapped routes. It satisfies the Store interface
// with empty implementations so no NATS connection is needed.
type stubIdempotencyStore struct{}

func (s *stubIdempotencyStore) Get(_ context.Context, _ string) (idempotency.Entry, bool, error) {
	return idempotency.Entry{}, false, nil
}

func (s *stubIdempotencyStore) Put(_ context.Context, _ string, _ idempotency.Entry) error {
	return nil
}

func (s *stubIdempotencyStore) Reserve(_ context.Context, _ string, _ string) (bool, error) {
	return true, nil
}

func (s *stubIdempotencyStore) Release(_ context.Context, _ string) error {
	return nil
}

var _ idempotency.Store = (*stubIdempotencyStore)(nil)

// stubEnforcer allows all RBAC checks through. Used only in route-coverage
// tests that never invoke business logic.
type stubEnforcer struct{}

func (s *stubEnforcer) Enforce(_ context.Context, _ string) error { return nil }

var _ handlers.Enforcer = (*stubEnforcer)(nil)

// stubPromQuerier returns empty results for every Prometheus query. Used to
// construct a SystemHealthHandler whose Handle method is callable.
type stubPromQuerier struct{}

func (s *stubPromQuerier) Query(_ context.Context, _ string) (interface { /* promclient.InstantVector */
}, error) {
	return nil, nil
}

// TestNewRouter_AllHandlerBranches_RegisterRoutes asserts that when all
// optional handler arguments are non-nil, the router registers the full
// expected route set without panicking.
func TestNewRouter_AllHandlerBranches_RegisterRoutes(t *testing.T) {
	idem := &stubIdempotencyStore{}
	inviteH := &handlers.InviteHandler{Enforcer: &stubEnforcer{}}
	usersH := &handlers.UsersHandler{}
	tenantsH := &handlers.TenantsHandler{}
	emailIntegrationH := handlers.NewEmailIntegrationHandler(nil, nil)
	orgUsersH := &handlers.OrgUsersHandler{}
	apiKeysH := &handlers.ApiKeysHandler{}
	featureFlagsH := &handlers.FeatureFlagsHandler{}
	platformUsersH := &handlers.PlatformUsersHandler{}
	providerKeysH := &handlers.ProviderKeysHandler{}

	// Must not panic.
	r := NewRouter(nil, idem, inviteH, usersH, tenantsH, emailIntegrationH, orgUsersH, apiKeysH, featureFlagsH, platformUsersH, providerKeysH, nil)

	// Helper: a non-404 response confirms the route is registered.
	routeExists := func(method, path string) bool {
		rec := httptest.NewRecorder()
		req := httptest.NewRequest(method, path, nil)
		r.ServeHTTP(rec, req)
		return rec.Code != http.StatusNotFound
	}

	// Spot-check one route from each optional handler block so every
	// nil-guard in NewRouter is exercised.
	for _, tc := range []struct {
		method, path, label string
	}{
		{http.MethodGet, "/api/v1/admin/users", "usersH"},
		{http.MethodGet, "/api/v1/admin/tenants", "tenantsH"},
		{http.MethodGet, "/api/v1/admin/integrations/email", "emailIntegrationH"},
		{http.MethodDelete, "/api/v1/admin/orgs/org1/users/user1", "orgUsersH"},
		{http.MethodGet, "/api/v1/admin/api-keys", "apiKeysH"},
		{http.MethodGet, "/api/v1/admin/feature-flags", "featureFlagsH"},
		{http.MethodGet, "/api/v1/admin/platform-users", "platformUsersH"},
		{http.MethodGet, "/api/v1/admin/integrations/providers", "providerKeysH"},
	} {
		if !routeExists(tc.method, tc.path) {
			t.Errorf("%s %s not registered (%s branch)", tc.method, tc.path, tc.label)
		}
	}
}

// ---------------------------------------------------------------------------
// F11 sub-PR 3 — trusted-proxy client-IP resolution.
//
// NewRouter wires security.ClientIPMiddleware(trustedProxyCIDRs) in place of
// middleware.RealIP. These tests drive the defaultRateLimit-guarded
// GET /api/v1/admin/system-health route (auth.RequireOrgClaim lets a
// populated-org token through; the handler falls back to 503 with no
// PromQuerier wired) through a REAL router with a REAL signed JWT — mirroring
// router_org_claim_test.go's OIDC stub helpers (same package, reused as-is,
// not modified) — to prove the httprate KeyByOrgIDAndIP bucket is keyed off
// the trusted-proxy-aware client IP, not a header any untrusted peer can set.
// ---------------------------------------------------------------------------

func TestNewRouter_ForgedHeaders_FromUntrustedPeer_DoNotChangeRateLimitKey(t *testing.T) {
	stub := newOrgClaimOIDCStub(t)
	verifier := newOrgClaimVerifier(t, stub, orgClaimTestAudience)
	token := stub.mintToken(t, orgClaimTestAudience, "org-rate-untrusted", nil)

	// No CIDRs trusted.
	r := NewRouter(verifier, &stubIdempotencyStore{}, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil)

	const untrustedPeer = "198.51.100.5:9999"
	const forgedIP = "203.0.113.222"

	for i := 0; i < defaultRateLimit+20; i++ {
		req := httptest.NewRequest(http.MethodGet, "/api/v1/admin/system-health", nil)
		req.Header.Set("Authorization", "Bearer "+token)
		req.RemoteAddr = untrustedPeer
		req.Header.Set("X-Forwarded-For", forgedIP)
		rec := httptest.NewRecorder()
		r.ServeHTTP(rec, req)
	}

	// A caller whose REAL RemoteAddr is the forged IP, same org, must be
	// untouched — proving the untrusted peer's X-Forwarded-For was ignored.
	req := httptest.NewRequest(http.MethodGet, "/api/v1/admin/system-health", nil)
	req.Header.Set("Authorization", "Bearer "+token)
	req.RemoteAddr = forgedIP + ":1234"
	rec := httptest.NewRecorder()
	r.ServeHTTP(rec, req)
	require.NotEqual(t, http.StatusTooManyRequests, rec.Code,
		"real client at the forged IP got 429 — an untrusted peer's X-Forwarded-For "+
			"was honored, colliding rate-limit buckets")
}

func TestNewRouter_TrustedProxy_KeysRateLimitByRealClientIPFromXFF(t *testing.T) {
	stub := newOrgClaimOIDCStub(t)
	verifier := newOrgClaimVerifier(t, stub, orgClaimTestAudience)
	token := stub.mintToken(t, orgClaimTestAudience, "org-rate-trusted", nil)

	trusted := []netip.Prefix{netip.MustParsePrefix("10.0.0.0/8")}
	r := NewRouter(verifier, &stubIdempotencyStore{}, nil, nil, nil, nil, nil, nil, nil, nil, nil, trusted)

	const trustedProxyPeer = "10.0.0.1:5555"
	const realClientA = "203.0.113.60"

	got429 := false
	for i := 0; i < defaultRateLimit+20; i++ {
		req := httptest.NewRequest(http.MethodGet, "/api/v1/admin/system-health", nil)
		req.Header.Set("Authorization", "Bearer "+token)
		req.RemoteAddr = trustedProxyPeer
		req.Header.Set("X-Forwarded-For", realClientA)
		rec := httptest.NewRecorder()
		r.ServeHTTP(rec, req)
		if rec.Code == http.StatusTooManyRequests {
			got429 = true
			break
		}
	}
	require.True(t, got429, "real client A behind the trusted proxy never got 429 — "+
		"the defaultRateLimit bucket never tripped")

	// A DIFFERENT real client behind the SAME trusted proxy, same org, gets
	// its own bucket — proves the key is the XFF-resolved client IP, not the
	// proxy's shared RemoteAddr.
	req := httptest.NewRequest(http.MethodGet, "/api/v1/admin/system-health", nil)
	req.Header.Set("Authorization", "Bearer "+token)
	req.RemoteAddr = trustedProxyPeer
	req.Header.Set("X-Forwarded-For", "203.0.113.61")
	rec := httptest.NewRecorder()
	r.ServeHTTP(rec, req)
	require.NotEqual(t, http.StatusTooManyRequests, rec.Code,
		"a distinct real client IP behind the same trusted proxy got 429 — the "+
			"limiter keyed on the proxy's RemoteAddr instead of the XFF-resolved IP")
}


