package server

import (
	"context"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/observability"
)

// TestMain initialises the metrics registry once for this package so that
// NewRouter (which calls HTTPMetricsMiddleware) does not panic in tests.
func TestMain(m *testing.M) {
	// SetupMeter must be called before any NewRouter call that uses
