// Package server provides the chi router constructor for admin-bff.
//
// Splitting router wiring out of cmd/server/main.go allows integration tests
// to call NewRouter with stub dependencies and inspect the route tree via
// chi.Walk without starting a real HTTP listener.
package server

import (
	"net/http"
	"net/netip"
	"time"

	"github.com/go-chi/chi/v5"
	"github.com/go-chi/chi/v5/middleware"
	"github.com/go-chi/httprate"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/httpserver"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/idempotency"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/observability"
	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/security"
	"github.com/zenithflowinc/omnicore-platform/services/admin-bff/internal/handlers"
)

// Rate-limit budgets per (org_id, IP) bucket. T1.7 from the 2026-05-05
// foundation-readiness review.
//
// These are deliberately generous for normal admin traffic and tight on
// the invite endpoint, which both writes a row and round-trips the
// Keycloak admin API. A misbehaving admin client cannot drive Keycloak
// past these rates from a single (org, IP) bucket; legitimate operators
// fronting a high-volume migrator go through the migrator's own RPC
// path, not this endpoint.
const (
	defaultRateLimit = 600         // requests per window
	inviteRateLimit  = 60          // requests per window — tighter for the write+IdP endpoint
	rateLimitWindow  = time.Minute //
)

// NewRouter builds and returns the admin-bff chi.Router.
//
// Returning chi.Router (rather than http.Handler) lets callers use chi.Walk
// for route inspection in integration tests while still satisfying http.Handler
// for net/http server wiring.
//
// Parameters mirror the dependencies wired in cmd/server/main.go:
//   - verifier: JWT verifier used by auth.HTTPMiddleware (may be nil in tests —
//     the middleware handles a nil verifier by rejecting AuthRequired requests).
//   - idemStore: idempotency.Store for the invite endpoint.
//   - inviteH: handler for POST /api/v1/admin/users/invite.
//   - featureFlagsH: handler for GET/PUT /api/v1/admin/feature-flags (nil-safe).
//   - platformUsersH: handler for GET /api/v1/admin/platform-users (nil-safe).
//   - providerKeysH: handler for GET/PUT /api/v1/admin/integrations/providers (nil-safe).
//   - trustedProxyCIDRs: CIDR ranges trusted to supply a forwarded client IP
//     (X-Forwarded-For / True-Client-IP) via security.ClientIPMiddleware.
//     Sourced from cfg.TrustedProxyCIDRs in main.go. A nil/empty slice trusts
//     nothing, so every request's client IP falls back to RemoteAddr — the
//     same posture middleware.RealIP had before it accepted headers from any
//     peer.
//   - systemHealthH: handler for GET /api/v1/admin/system-health (nil-safe).
func NewRouter(
	verifier *auth.JWTVerifier,
	idemStore idempotency.Store,
	inviteH *handlers.InviteHandler,
	usersH *handlers.UsersHandler,
	tenantsH *handlers.TenantsHandler,
	emailIntegrationH *handlers.EmailIntegrationHandler,
	orgUsersH *handlers.OrgUsersHandler,
	apiKeysH *handlers.ApiKeysHandler,
	featureFlagsH *handlers.FeatureFlagsHandler,
	platformUsersH *handlers.PlatformUsersHandler,
	providerKeysH *handlers.ProviderKeysHandler,
	trustedProxyCIDRs []netip.Prefix,
	systemHealthH ...*handlers.SystemHealthHandler,
) chi.Router {
	r := chi.NewRouter()
	r.Use(middleware.RequestID)
	r.Use(security.ClientIPMiddleware(trustedProxyCIDRs))
	r.Use(middleware.Recoverer)
	r.Use(security.Middleware)
	r.Use(observability.HTTPMetricsMiddleware())

	// /healthz and /metrics are PUBLIC — no JWT required. Prometheus scrapes
	// /metrics without a bearer token (analogous to the existing /healthz).
	r.Get("/healthz", func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte("ok"))
	})
	r.Handle("/metrics", observability.MetricsHandler())

	// /api/v1/admin/* — require a valid bearer token. Rate-limited per
	// (org_id, IP) bucket; the invite endpoint gets a tighter budget
	// because each call writes a DB row and round-trips Keycloak's
	// admin API (T1.7).
	r.Group(func(r chi.Router) {
		r.Use(auth.HTTPMiddleware(verifier, auth.AuthRequired))
		// F31: reject an empty org_id claim (unless migration:write-exempt)
		// before any admin-bff handler runs. Without this, a caller whose
		// JWT carries claims but no org_id sails through every downstream
		// handler-level cross-org check that (like invite.go's, pre-fix)
		// conditions itself on claims.OrgID != "".
		r.Use(auth.RequireOrgClaim())
		r.Use(httprate.Limit(defaultRateLimit, rateLimitWindow,
			httprate.WithKeyFuncs(security.KeyByOrgIDAndIP)))
		// admin-bff has no streaming/SSE/multipart-upload routes — every
		// handler below is ordinary request/response CRUD, so a single
		// per-request deadline at the outer group is safe. 30s matches
		// grpcclient.TierDefault, the platform's standard REST budget.
		r.Use(httpserver.Timeout(30 * time.Second))

		r.Group(func(r chi.Router) {
			r.Use(httprate.Limit(inviteRateLimit, rateLimitWindow,
				httprate.WithKeyFuncs(security.KeyByOrgIDAndIP)))
			r.With(idempotency.Middleware(idemStore)).Post("/api/v1/admin/users/invite", inviteH.Invite)
		})

		// Users endpoints (Phase 3a read, 3b write, 3c status flips):
		// no idempotency middleware on List (reads are idempotent by
		// default); Patch + Suspend + Reactivate are wrapped because
		// they mutate state. usersH may be nil in route-audit tests
		// that only inspect the route tree — the registrations skip
		// in that case.
		if usersH != nil {
			r.Get("/api/v1/admin/users", usersH.List)
			r.With(idempotency.Middleware(idemStore)).
				Patch("/api/v1/admin/users/{id}", usersH.Patch)
			r.With(idempotency.Middleware(idemStore)).
				Post("/api/v1/admin/users/{id}/suspend", usersH.Suspend)
			r.With(idempotency.Middleware(idemStore)).
				Post("/api/v1/admin/users/{id}/reactivate", usersH.Reactivate)
			// Phase 3d: memberships read + 2FA admin.
			// GET endpoints are inherently idempotent — no middleware.
			// Writes (require / reset) sit behind idempotency middleware.
			r.Get("/api/v1/admin/users/{id}/memberships", usersH.ListMemberships)
			r.Get("/api/v1/admin/users/{id}/2fa", usersH.Get2FA)
			r.With(idempotency.Middleware(idemStore)).
				Post("/api/v1/admin/users/{id}/2fa/require", usersH.Require2FA)
			r.With(idempotency.Middleware(idemStore)).
				Delete("/api/v1/admin/users/{id}/2fa", usersH.Reset2FA)
		}

		// Phase 4a — Tenants read path. GET is inherently idempotent; no
		// middleware. tenantsH may be nil in route-audit tests that only
		// inspect the route tree.
		// Phase 4b — Get-by-id + PATCH for name/slug edit; PATCH sits
		// behind idempotency middleware because it mutates state.
		// Phase 4c — POST creates a tenant via org-svc Bootstrap;
		// idempotency middleware deduplicates client retries.
		if tenantsH != nil {
			r.Get("/api/v1/admin/tenants", tenantsH.List)
			r.Get("/api/v1/admin/tenants/{id}", tenantsH.Get)
			r.With(idempotency.Middleware(idemStore)).
				Patch("/api/v1/admin/tenants/{id}", tenantsH.Patch)
			r.With(idempotency.Middleware(idemStore)).
				Post("/api/v1/admin/tenants", tenantsH.Create)
			// Phase 4f — soft-delete. DELETE is idempotent (flipping the same
			// status twice is a no-op), so we wrap it with idempotency
			// middleware for retry-safety rather than for dedup semantics.
			r.With(idempotency.Middleware(idemStore)).
				Delete("/api/v1/admin/tenants/{id}", tenantsH.Delete)
			// Phase 4g — restore (inverse of Delete), workspace member
			// roster, and Add Member by email type-ahead. Writes sit
			// behind idempotency middleware for retry-safety.
			r.With(idempotency.Middleware(idemStore)).
				Post("/api/v1/admin/tenants/{id}/activate", tenantsH.Activate)
			r.Get("/api/v1/admin/tenants/{id}/members", tenantsH.ListMembers)
			r.With(idempotency.Middleware(idemStore)).
				Post("/api/v1/admin/tenants/{id}/members", tenantsH.AddMember)
			r.With(idempotency.Middleware(idemStore)).
				Delete("/api/v1/admin/tenants/{id}/members/{user_id}", tenantsH.RemoveMember)
			r.Get("/api/v1/admin/tenants/{id}/members/lookup", tenantsH.LookupMemberByEmail)
			// Phase 4i — status dropdown. Idempotent on
			// (tenant_id, target_status, trial_days) — middleware
			// dedupes retries.
			r.With(idempotency.Middleware(idemStore)).
				Post("/api/v1/admin/tenants/{id}/status", tenantsH.UpdateStatus)
			// Phase 4j — inline role popover on the members table.
			// POST (not PATCH) so idempotency middleware can dedupe retries.
			r.With(idempotency.Middleware(idemStore)).
				Post("/api/v1/admin/tenants/{id}/members/{user_id}/role", tenantsH.UpdateMemberRole)
		}

		// Sub-PR 11 — Org-level email integration (admin-only). PATCH
		// is wrapped in idempotency middleware because it writes a
		// row + secrets; GET is inherently idempotent.
		if emailIntegrationH != nil {
			r.Get("/api/v1/admin/integrations/email", emailIntegrationH.Get)
			r.With(idempotency.Middleware(idemStore)).
				Patch("/api/v1/admin/integrations/email", emailIntegrationH.Update)
		}

		// Platform provider keys (shared Monitor feed API keys: Serper /
		// Apify / Jina). GET is read-only — no idempotency middleware. PUT
		// mutates state (writes the secret into Vault + emits audit/outbox)
		// and is wrapped with idempotency middleware for retry-safety.
		// Platform-admin gated inside the handler (realm "admin" role check).
		// The response NEVER carries the raw secret. providerKeysH may be nil
		// in route-audit tests that only inspect the route tree.
		if providerKeysH != nil {
			r.Get("/api/v1/admin/integrations/providers", providerKeysH.List)
			r.With(idempotency.Middleware(idemStore)).
				Put("/api/v1/admin/integrations/providers/{provider}", providerKeysH.Update)
		}

		// Full removal of a user from an organization. Orchestrates
		// org-svc RemoveUserFromOrg (authoritative owner/admin + self +
		// last-owner gate) then identity-svc RemoveFromOrg. DELETE is
		// idempotent (re-removing is a no-op), so we wrap it with the
		// idempotency middleware for retry-safety. orgUsersH may be nil
		// in route-audit tests that only inspect the route tree.
		if orgUsersH != nil {
			r.With(idempotency.Middleware(idemStore)).
				Delete("/api/v1/admin/orgs/{org_id}/users/{user_id}", orgUsersH.RemoveUserFromOrg)
		}

		// Admin API keys (machine credentials). GET is inherently
		// idempotent; Create / Rotate / Revoke mutate state and sit behind
		// the idempotency middleware for retry-safety. The one-time
		// plaintext secret is surfaced only in the Create / Rotate response
		// bodies. apiKeysH may be nil in route-audit tests that only
		// inspect the route tree.
		if apiKeysH != nil {
			r.Get("/api/v1/admin/api-keys", apiKeysH.List)
			r.With(idempotency.Middleware(idemStore)).
				Post("/api/v1/admin/api-keys", apiKeysH.Create)
			r.With(idempotency.Middleware(idemStore)).
				Post("/api/v1/admin/api-keys/{id}/rotate", apiKeysH.Rotate)
			r.With(idempotency.Middleware(idemStore)).
				Post("/api/v1/admin/api-keys/{id}/revoke", apiKeysH.Revoke)
		}

		// Platform feature-flag toggles (Phase 3, feature/admin-feature-flags).
		// GET is read-only — no idempotency middleware. PUT mutates state and
		// is wrapped with idempotency middleware for retry-safety.
		// Platform-admin gated inside the handler (realm "admin" role check).
		// featureFlagsH may be nil in route-audit tests that only inspect the
		// route tree.
		if featureFlagsH != nil {
			r.Get("/api/v1/admin/feature-flags", featureFlagsH.List)
			r.With(idempotency.Middleware(idemStore)).
				Put("/api/v1/admin/feature-flags/{key}", featureFlagsH.Update)
		}

		// Platform user management (system admin). Keyed by Keycloak sub, not
		// identity.users.id — see handlers.PlatformUsersHandler. GET needs no
		// idempotency middleware; the writes below do.
		//
		// ResetPassword mutates Keycloak state (mints + sets a new temporary
		// password), so it sits behind idempotency middleware like every
		// other write in this file — for retry-safety, NOT to replay the
		// password: the handler sets X-Idempotency-Sensitive so the
		// middleware never caches the live credential in its 24h KV bucket.
		// A replayed request therefore gets back `"temporary_password": ""`,
		// not the original — a caller that loses the password must issue a
		// new reset rather than recover the old one.
		//
		// Delete orchestrates a multi-step fan-out (pre-flight every org,
		// then per-org removal, then the terminal Keycloak purge) where
		// every individual step is idempotent but there is no compensating
		// rollback across them — idempotency middleware is what makes a
		// retry after a partial failure converge instead of erroring.
		if platformUsersH != nil {
			r.Get("/api/v1/admin/platform-users", platformUsersH.List)
			r.With(idempotency.Middleware(idemStore)).
				Post("/api/v1/admin/platform-users/{sub}/reset-password", platformUsersH.ResetPassword)
			r.With(idempotency.Middleware(idemStore)).
				Delete("/api/v1/admin/platform-users/{sub}", platformUsersH.Delete)
		}

		// System health aggregator (sub-PR 2). GET is read-only — no
		// idempotency middleware. Platform-tier gated inside the handler
		// (realm "admin" role check). systemHealthH may be nil in tests that
		// only inspect the route tree; the guard means the route is still
		// registered (we pass a non-nil handler in production and in the
		// route-audit test).
		//
		// We register the route unconditionally using an inline http.HandlerFunc
		// that delegates to the optional handler so that chi.Walk always sees
		// the route — this lets the route-audit integration test confirm it is
		// auth-gated without requiring a real PromQuerier.
		var shH *handlers.SystemHealthHandler
		if len(systemHealthH) > 0 {
			shH = systemHealthH[0]
		}
		r.Get("/api/v1/admin/system-health", func(w http.ResponseWriter, req *http.Request) {
			if shH != nil {
				shH.Handle(w, req)
				return
			}
			w.WriteHeader(http.StatusServiceUnavailable)
		})
	})

	return r
}


