	orgUsersH := &handlers.OrgUsersHandler{}
	apiKeysH := &handlers.ApiKeysHandler{}
	featureFlagsH := &handlers.FeatureFlagsHandler{}
	platformUsersH := &handlers.PlatformUsersHandler{}
	providerKeysH := &handlers.ProviderKeysHandler{}

	// Must not panic.
	r := NewRouter(nil, idem, inviteH, usersH, tenantsH, emailIntegrationH, orgUsersH, apiKeysH, featureFlagsH, platformUsersH, providerKeysH, nil)

	// Helper: a non-404 response confirms the route is registered.
	routeExists := func(method, path string) bool {
		rec := httptest.NewRecorder()
		req := httptest.NewRequest(method, path, nil)
		r.ServeHTTP(rec, req)
		return rec.Code != http.StatusNotFound
	}

	// Spot-check one route from each optional handler block so every
	// nil-guard in NewRouter is exercised.
	for _, tc := range []struct {
		method, path, label string
	}{
		{http.MethodGet, "/api/v1/admin/users", "usersH"},
		{http.MethodGet, "/api/v1/admin/tenants", "tenantsH"},
		{http.MethodGet, "/api/v1/admin/integrations/email", "emailIntegrationH"},
		{http.MethodDelete, "/api/v1/admin/orgs/org1/users/user1", "orgUsersH"},
		{http.MethodGet, "/api/v1/admin/api-keys", "apiKeysH"},
		{http.MethodGet, "/api/v1/admin/feature-flags", "featureFlagsH"},
		{http.MethodGet, "/api/v1/admin/platform-users", "platformUsersH"},
		{http.MethodGet, "/api/v1/admin/integrations/providers", "providerKeysH"},
