// ---------------------------------------------------------------------------
// F11 sub-PR 3 — trusted-proxy client-IP resolution.
//
// NewRouter wires security.ClientIPMiddleware(trustedProxyCIDRs) in place of
// middleware.RealIP. These tests drive the defaultRateLimit-guarded
// GET /api/v1/admin/system-health route (auth.RequireOrgClaim lets a
// populated-org token through; the handler falls back to 503 with no
// PromQuerier wired) through a REAL router with a REAL signed JWT — mirroring
// router_org_claim_test.go's OIDC stub helpers (same package, reused as-is,
// not modified) — to prove the httprate KeyByOrgIDAndIP bucket is keyed off
// the trusted-proxy-aware client IP, not a header any untrusted peer can set.
// ---------------------------------------------------------------------------

func TestNewRouter_ForgedHeaders_FromUntrustedPeer_DoNotChangeRateLimitKey(t *testing.T) {
	stub := newOrgClaimOIDCStub(t)
	verifier := newOrgClaimVerifier(t, stub, orgClaimTestAudience)
	token := stub.mintToken(t, orgClaimTestAudience, "org-rate-untrusted", nil)

	// No CIDRs trusted.
	r := NewRouter(verifier, &stubIdempotencyStore{}, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil)

	const untrustedPeer = "198.51.100.5:9999"
	const forgedIP = "203.0.113.222"

	for i := 0; i < defaultRateLimit+20; i++ {
		req := httptest.NewRequest(http.MethodGet, "/api/v1/admin/system-health", nil)
		req.Header.Set("Authorization", "Bearer "+token)
		req.RemoteAddr = untrustedPeer
		req.Header.Set("X-Forwarded-For", forgedIP)
		rec := httptest.NewRecorder()
		r.ServeHTTP(rec, req)
	}

	// A caller whose REAL RemoteAddr is the forged IP, same org, must be
	// untouched — proving the untrusted peer's X-Forwarded-For was ignored.
	req := httptest.NewRequest(http.MethodGet, "/api/v1/admin/system-health", nil)
	req.Header.Set("Authorization", "Bearer "+token)
	req.RemoteAddr = forgedIP + ":1234"
	rec := httptest.NewRecorder()
	r.ServeHTTP(rec, req)
	require.NotEqual(t, http.StatusTooManyRequests, rec.Code,
		"real client at the forged IP got 429 — an untrusted peer's X-Forwarded-For "+
			"was honored, colliding rate-limit buckets")
}

func TestNewRouter_TrustedProxy_KeysRateLimitByRealClientIPFromXFF(t *testing.T) {
	stub := newOrgClaimOIDCStub(t)
	verifier := newOrgClaimVerifier(t, stub, orgClaimTestAudience)
	token := stub.mintToken(t, orgClaimTestAudience, "org-rate-trusted", nil)

	trusted := []netip.Prefix{netip.MustParsePrefix("10.0.0.0/8")}
	r := NewRouter(verifier, &stubIdempotencyStore{}, nil, nil, nil, nil, nil, nil, nil, nil, nil, trusted)

	const trustedProxyPeer = "10.0.0.1:5555"
	const realClientA = "203.0.113.60"

	got429 := false
	for i := 0; i < defaultRateLimit+20; i++ {
		req := httptest.NewRequest(http.MethodGet, "/api/v1/admin/system-health", nil)
		req.Header.Set("Authorization", "Bearer "+token)
		req.RemoteAddr = trustedProxyPeer
		req.Header.Set("X-Forwarded-For", realClientA)
		rec := httptest.NewRecorder()
		r.ServeHTTP(rec, req)
		if rec.Code == http.StatusTooManyRequests {
			got429 = true
			break
		}
	}
	require.True(t, got429, "real client A behind the trusted proxy never got 429 — "+
		"the defaultRateLimit bucket never tripped")

	// A DIFFERENT real client behind the SAME trusted proxy, same org, gets
	// its own bucket — proves the key is the XFF-resolved client IP, not the
	// proxy's shared RemoteAddr.
	req := httptest.NewRequest(http.MethodGet, "/api/v1/admin/system-health", nil)
	req.Header.Set("Authorization", "Bearer "+token)
	req.RemoteAddr = trustedProxyPeer
	req.Header.Set("X-Forwarded-For", "203.0.113.61")
	rec := httptest.NewRecorder()
	r.ServeHTTP(rec, req)
	require.NotEqual(t, http.StatusTooManyRequests, rec.Code,
		"a distinct real client IP behind the same trusted proxy got 429 — the "+
			"limiter keyed on the proxy's RemoteAddr instead of the XFF-resolved IP")
}


