}

// TestNewRouter_MetricsRoute_IsRegistered asserts that GET /metrics is
// registered as a publicly accessible route (no JWT required) and returns
// HTTP 200 with a Prometheus text-format body.
//
// The route must be mounted OUTSIDE the auth-gated group so Prometheus can
// scrape it without a bearer token (analogous to /healthz). The test calls
// the route directly and asserts 200 + Content-Type: text/plain.
func TestNewRouter_MetricsRoute_IsRegistered(t *testing.T) {
	r := NewRouter(nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil)

	rec := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, "/metrics", nil)
	r.ServeHTTP(rec, req)

	if rec.Code != http.StatusOK {
		t.Errorf("GET /metrics status = %d, want 200 — metrics route not registered or auth-gated", rec.Code)
	}

	ct := rec.Header().Get("Content-Type")
	if !strings.HasPrefix(ct, "text/plain") {
		t.Errorf("GET /metrics Content-Type = %q, want text/plain... — not Prometheus format", ct)
	}
