// header (no token). If it were inside the auth group it would return 401.
func TestNewRouter_MetricsRoute_IsNotAuthGated(t *testing.T) {
	r := NewRouter(nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil)

	rec := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, "/metrics", nil)
	// Deliberately no Authorization header.
	r.ServeHTTP(rec, req)

	if rec.Code == http.StatusUnauthorized {
		t.Error("GET /metrics returned 401 — route is auth-gated; /metrics must be public like /healthz")
