package server

// router_org_claim_test.go — F31, admin-bff mount point.
//
// router_coverage_test.go / router_metrics_test.go only ever call the real
// router with verifier=nil and no Authorization header, so every assertion
// there is registration-shaped ("does this route exist / return non-404").
// That is exactly the vacuous pattern F31 warns against: a route sitting
// behind zero middleware and a route sitting behind auth.RequireOrgClaim()
// both look identical to a check that never sends a real, signed JWT through
// auth.HTTPMiddleware's real verifier.
//
// These tests boot a minimal in-process OIDC issuer (mirroring
// platform/libs/go/auth's own oidc_stub_test.go and range-bff's
// server_platform_gate_test.go pv0IDCStub), build a REAL *auth.JWTVerifier
// against it, mint REAL signed JWTs, and drive requests through the REAL
// server.NewRouter(...) — so a regression that dropped the
// auth.RequireOrgClaim() mount at router.go:81-87 would show up as an actual
// 200/503 instead of the 403 asserted below, not as a passing "route exists"
// check.
//
// GET /api/v1/admin/system-health is the target route: with systemHealthH
// omitted (the variadic left empty), NewRouter still registers the route but
// its handler unconditionally writes 503 — a safe, side-effect-free signal
// that the request reached the handler at all, distinguishing "blocked by
// RequireOrgClaim" (403, handler never runs) from "let through" (503, handler
// ran) without needing a real PromQuerier.

import (
	"context"
	"crypto/rand"
	"crypto/rsa"
	"encoding/base64"
	"encoding/json"
	"math/big"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	jose "github.com/go-jose/go-jose/v4"
	josejwt "github.com/go-jose/go-jose/v4/jwt"
	"github.com/stretchr/testify/require"

	"github.com/zenithflowinc/omnicore-platform/platform/libs/go/auth"
)

// orgClaimOIDCStub is a minimal in-process OIDC issuer, local to this file so
// the "server" package doesn't need to import platform/libs/go/auth's
// unexported test helpers.
type orgClaimOIDCStub struct {
	srv    *httptest.Server
	key    *rsa.PrivateKey
	kid    string
	Issuer string
}

func newOrgClaimOIDCStub(t *testing.T) *orgClaimOIDCStub {
	t.Helper()

	key, err := rsa.GenerateKey(rand.Reader, 2048)
	require.NoError(t, err)
	stub := &orgClaimOIDCStub{key: key, kid: "org-claim-test-key-1"}

	mux := http.NewServeMux()
	mux.HandleFunc("/.well-known/openid-configuration", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]any{
			"issuer":                                stub.Issuer,
			"authorization_endpoint":                stub.Issuer + "/authorize",
			"token_endpoint":                        stub.Issuer + "/token",
			"jwks_uri":                              stub.Issuer + "/keys",
			"id_token_signing_alg_values_supported": []string{"RS256"},
			"response_types_supported":              []string{"code"},
			"subject_types_supported":               []string{"public"},
		})
	})
	mux.HandleFunc("/keys", func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		n := base64.RawURLEncoding.EncodeToString(key.PublicKey.N.Bytes())
		e := base64.RawURLEncoding.EncodeToString(big.NewInt(int64(key.PublicKey.E)).Bytes())
		_ = json.NewEncoder(w).Encode(map[string]any{
			"keys": []map[string]any{{
				"kty": "RSA", "alg": "RS256", "use": "sig", "kid": stub.kid, "n": n, "e": e,
			}},
		})
	})

	stub.srv = httptest.NewServer(mux)
	stub.Issuer = stub.srv.URL
	t.Cleanup(stub.srv.Close)
	return stub
}

// mintToken signs a JWT this stub's verifier will accept.
func (s *orgClaimOIDCStub) mintToken(t *testing.T, audience, orgID string, scopes []string) string {
	t.Helper()
	sig, err := jose.NewSigner(
		jose.SigningKey{Algorithm: jose.RS256, Key: s.key},
		(&jose.SignerOptions{}).WithType("JWT").WithHeader("kid", s.kid),
	)
	require.NoError(t, err)

	now := time.Now()
	std := josejwt.Claims{
		Issuer:   s.Issuer,
		Subject:  "org-claim-test-caller",
		Audience: josejwt.Audience{audience},
		IssuedAt: josejwt.NewNumericDate(now),
		Expiry:   josejwt.NewNumericDate(now.Add(5 * time.Minute)),
	}
	extra := struct {
		OrgID       string   `json:"org_id,omitempty"`
		Permissions []string `json:"permissions,omitempty"`
	}{OrgID: orgID, Permissions: scopes}

	signed, err := josejwt.Signed(sig).Claims(std).Claims(extra).Serialize()
	require.NoError(t, err)
	return signed
}

func newOrgClaimVerifier(t *testing.T, stub *orgClaimOIDCStub, audience string) *auth.JWTVerifier {
	t.Helper()
	v, err := auth.NewJWTVerifier(context.Background(), stub.Issuer, "", audience)
	require.NoError(t, err)
	return v
}

