// /api/v1/admin/system-health's fallback (503, no PromQuerier needed) is the
// only thing that can run if RequireOrgClaim lets the request through.
func newOrgClaimTestRouter(verifier *auth.JWTVerifier) http.Handler {
	return NewRouter(verifier, &stubIdempotencyStore{}, nil, nil, nil, nil, nil, nil, nil, nil, nil, nil)
}

const orgClaimTestAudience = "admin-bff"

// TestRouter_RequireOrgClaim_RejectsEmptyOrgClaim is the F31 regression at
// the router-mount level: a caller with a validly-signed JWT that carries an
// EMPTY org_id, and no migration:write scope, must be 403'd by
// auth.RequireOrgClaim() BEFORE the system-health fallback handler ever runs
// (which would otherwise show up as 503, not 403).
func TestRouter_RequireOrgClaim_RejectsEmptyOrgClaim(t *testing.T) {
	stub := newOrgClaimOIDCStub(t)
	verifier := newOrgClaimVerifier(t, stub, orgClaimTestAudience)
	token := stub.mintToken(t, orgClaimTestAudience, "", nil)

	r := newOrgClaimTestRouter(verifier)
	req := httptest.NewRequest(http.MethodGet, "/api/v1/admin/system-health", nil)
	req.Header.Set("Authorization", "Bearer "+token)
	rec := httptest.NewRecorder()
	r.ServeHTTP(rec, req)

	require.Equal(t, http.StatusForbidden, rec.Code,
		"an empty org_id claim without migration:write must be rejected by the router's RequireOrgClaim mount; body: %s", rec.Body.String())
	require.Contains(t, rec.Body.String(), `"forbidden"`)
}

// TestRouter_RequireOrgClaim_AllowsPopulatedOrgClaim is the positive control:
// an ordinary caller with a populated org_id claim must reach the handler
// (503 from the no-op system-health fallback), proving the mount doesn't
// block legitimate traffic.
func TestRouter_RequireOrgClaim_AllowsPopulatedOrgClaim(t *testing.T) {
	stub := newOrgClaimOIDCStub(t)
	verifier := newOrgClaimVerifier(t, stub, orgClaimTestAudience)
	token := stub.mintToken(t, orgClaimTestAudience, "org-a", nil)

	r := newOrgClaimTestRouter(verifier)
	req := httptest.NewRequest(http.MethodGet, "/api/v1/admin/system-health", nil)
	req.Header.Set("Authorization", "Bearer "+token)
	rec := httptest.NewRecorder()
	r.ServeHTTP(rec, req)

	require.Equal(t, http.StatusServiceUnavailable, rec.Code,
		"a populated org_id claim must reach the handler, not be blocked; body: %s", rec.Body.String())
}

