func TestRouter_RequireOrgClaim_AllowsMigrationWriteScopeWithEmptyOrgClaim(t *testing.T) {
	stub := newOrgClaimOIDCStub(t)
	verifier := newOrgClaimVerifier(t, stub, orgClaimTestAudience)
	token := stub.mintToken(t, orgClaimTestAudience, "", []string{"migration:write"})

	r := newOrgClaimTestRouter(verifier)
	req := httptest.NewRequest(http.MethodGet, "/api/v1/admin/system-health", nil)
	req.Header.Set("Authorization", "Bearer "+token)
	rec := httptest.NewRecorder()
	r.ServeHTTP(rec, req)

	require.Equal(t, http.StatusServiceUnavailable, rec.Code,
		"migration:write must exempt an empty org_id claim; body: %s", rec.Body.String())
}

// TestRouter_RequireOrgClaim_NoToken_Returns401 rounds out the full chain:
// no bearer token at all must 401 from auth.HTTPMiddleware, never reaching
// RequireOrgClaim or the handler.
func TestRouter_RequireOrgClaim_NoToken_Returns401(t *testing.T) {
	stub := newOrgClaimOIDCStub(t)
	verifier := newOrgClaimVerifier(t, stub, orgClaimTestAudience)

	r := newOrgClaimTestRouter(verifier)
	req := httptest.NewRequest(http.MethodGet, "/api/v1/admin/system-health", nil)
	rec := httptest.NewRecorder()
	r.ServeHTTP(rec, req)

	require.Equal(t, http.StatusUnauthorized, rec.Code, "body: %s", rec.Body.String())
